import { d as db } from "../../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../../chunks/get-empresa-id.js";
import { s as serialize } from "../../../../../chunks/utils3.js";
const load = async ({ request, url }) => {
  const empresaId = await getEmpresaId(request);
  const page = Number(url.searchParams.get("page")) || 1;
  const limit = 5;
  const skip = (page - 1) * limit;
  const [recibos, total] = await Promise.all([
    db.documentoFiscal.findMany({
      where: {
        empresaId,
        tipoDocumento: "RECIBO"
      },
      include: {
        cliente: true,
        usuario: {
          select: {
            name: true
          }
        },
        itens: {
          include: {
            produto: {
              include: { taxa: true }
            }
          }
        }
      },
      orderBy: { dataEmissao: "desc" },
      take: limit,
      skip
    }),
    db.documentoFiscal.count({
      where: {
        empresaId,
        tipoDocumento: "RECIBO"
      }
    })
  ]);
  return serialize({
    recibos,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    }
  });
};
export {
  load
};
